package ie.tudublin

import java.io.File

fun printBoard(board: Array<IntArray>) {

    for (row in board) {

        println(row.joinToString(" "))

    }
}

fun main(args: Array<String>) {

    //check that the user provided a filename
    if (args.isEmpty()) {

        println("Please provide a Sudoku text file.")
        return

    }

    try {

        //read the Sudoku board from the file
        val lines = File(args[0]).readLines()
            .filter { it.isNotBlank() }

        // Convert each row into integers
        val board = lines.map { line ->

            line.trim().split(Regex("\\s+"))

                .map { it.toInt() }
                .toIntArray()

        }.toTypedArray()

        //check the board dimensions
        if (board.size != 9 || board.any { it.size != 9 }) {

            println("Invalid board: Sudoku must have 9 rows and 9 columns.")
            return

        }

        println("Input Sudoku board:")
        printBoard(board)

        //solve the Sudoku puzzle
        val sudoku = Sudoku(board)

        if (sudoku.solve()) {

            println("\nSolved Sudoku board:")
            printBoard(board)

        } else {

            println("\nCould not find a solution.")

        }

    } catch (e: Exception) {

        println("Error reading Sudoku file: ${e.message}")

    }
}

